// Serve the original MP4 bytes in bounded ranges; all other requests pass through.
self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
const manifests=new Map();
self.addEventListener('fetch',e=>{const url=new URL(e.request.url),base=new URL('./',self.registration.scope);if(url.origin!==base.origin||!url.pathname.startsWith(base.pathname+'media/'))return;const name=url.pathname.slice((base.pathname+'media/').length);if(!/^sunshine-(theme|promo)-hd\.mp4$/.test(name))return;e.respondWith(serve(e.request,url).catch(()=>new Response('Video unavailable',{status:503})));});
async function serve(req,url){const dir=url.href.replace(/\.mp4$/,'/');let m=manifests.get(dir);if(!m){const r=await fetch(dir+'manifest.json');if(!r.ok)throw Error('manifest');m=await r.json();manifests.set(dir,m)}let start=0,end=m.size-1,status=200;const range=req.headers.get('Range');if(range){const match=/^bytes=(\d*)-(\d*)$/.exec(range);if(!match)return new Response(null,{status:416,headers:{'Content-Range':`bytes */${m.size}`}});if(!match[1])start=Math.max(0,m.size-Number(match[2]));else{start=Number(match[1]);if(match[2])end=Math.min(end,Number(match[2]))}status=206}if(start>end||start>=m.size)return new Response(null,{status:416,headers:{'Content-Range':`bytes */${m.size}`}});const headers={'Content-Type':'video/mp4','Accept-Ranges':'bytes','Content-Length':String(end-start+1),'Cache-Control':'no-store'};if(status===206)headers['Content-Range']=`bytes ${start}-${end}/${m.size}`;if(req.method==='HEAD')return new Response(null,{status,headers});let pos=start;const abort=new AbortController();const stream=new ReadableStream({async pull(c){try{if(pos>end){c.close();return}const index=Math.floor(pos/m.chunkSize),r=await fetch(dir+m.chunks[index],{signal:abort.signal});if(!r.ok)throw Error('chunk');const bytes=new Uint8Array(await r.arrayBuffer()),offset=pos-index*m.chunkSize,n=Math.min(bytes.length-offset,end-pos+1);c.enqueue(bytes.subarray(offset,offset+n));pos+=n}catch(err){c.error(err)}},cancel(){abort.abort()}});return new Response(stream,{status,headers});}
